import { useForm, useWatch, FormProvider } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { Button } from '@/shadcn/components/ui/button.tsx'
import {
  Field,
  FieldGroup,
  FieldLabel,
  FieldSeparator,
} from '@/shadcn/components/ui/field.tsx'
import type { AnimalDetailResource } from '@/api/types/animals'
import {
  RadioGroup,
  RadioGroupItem,
} from '@/shadcn/components/ui/radio-group.tsx'
import { FormSection } from '@/components/form/FormSection'
import { FormGrid } from '@/components/form/FormGrid'
import { FormFieldWrapper } from '@/components/form/FormFieldWrapper'
import { FormBlocker } from '@/components/form/FormBlocker'
import { TextInput } from '@/components/field/TextInput.tsx'
import { UnitInput } from '@/components/field/UnitInput.tsx'
import { DateInput } from '@/components/field/DateInput.tsx'
import {
  zFieldDate,
  toDateFieldValue,
} from '@/components/field/DateInput.utils.ts'
import { Textarea } from '@/components/field/Textarea.tsx'
import { SelectInput } from '@/components/field/SelectInput.tsx'
import type { AnimalTypeResource } from '@/api/types/animal-types'
import {
  STRING_LENGTH_TEXTAREA,
  zFieldInt,
  zFieldString,
} from '@/components/field/TextInput.utils.ts'
import { COUNTRY_OPTIONS } from '@/lib/countries.ts'
import { X } from 'lucide-react'

const animalFormBasicSchema = z.object({
  animal_type_id: z.string().min(1, 'Pflichtfeld darf nicht leer sein'),
  // The number is locked in edit mode; legacy values may exceed 64 characters.
  animal_number: zFieldString(),
  name: zFieldString({ required: true }),
  old_name: zFieldString(),
  breed: zFieldString(),
  gender: z.enum(['male', 'female'], {
    error: 'Geschlecht muss gewählt werden',
  }),
  color: zFieldString(),
  weight_grams: zFieldInt({ max: 1000000 }),
  size_cm: zFieldInt({ max: 500 }),
  date_of_birth: zFieldDate,
  origin_country: zFieldString(),
  current_location: zFieldString(),
  current_country: z.string(),
  current_postal_code: zFieldString({ maxLength: 16 }),
  current_city: zFieldString(),
  intake_date: zFieldDate,
  character_description: zFieldString({ maxLength: STRING_LENGTH_TEXTAREA }),
  contract_notes: zFieldString({ maxLength: STRING_LENGTH_TEXTAREA }),
  internal_notes: zFieldString({ maxLength: STRING_LENGTH_TEXTAREA }),
})

export type AnimalFormBasicData = z.infer<typeof animalFormBasicSchema>

interface AnimalFormBasicProps {
  animalTypes: AnimalTypeResource[]
  defaultValues?: Partial<AnimalDetailResource>
  onSubmit: (data: AnimalFormBasicData) => Promise<void>
  onCancel?: () => void
  isSubmitting?: boolean
  submitLabel?: string
  showSecondaryButton?: boolean
  onSecondarySubmit?: () => void
  secondaryButtonLabel?: string
}

export function AnimalFormBasic({
  animalTypes = [],
  defaultValues,
  onSubmit,
  onCancel,
  isSubmitting = false,
  showSecondaryButton = false,
  onSecondarySubmit,
}: AnimalFormBasicProps) {
  const isEditMode = !!defaultValues?.animal_type

  // Preset animal_type_id if only one option and no default value
  const presetAnimalTypeId =
    !defaultValues?.animal_type_id && animalTypes.length === 1
      ? animalTypes[0].id
      : defaultValues?.animal_type_id

  const form = useForm<AnimalFormBasicData>({
    resolver: zodResolver(animalFormBasicSchema),
    defaultValues: {
      animal_type_id: presetAnimalTypeId,
      animal_number: defaultValues?.animal_number ?? '',
      name: defaultValues?.name ?? '',
      old_name: defaultValues?.old_name || '',
      breed: defaultValues?.breed || '',
      gender: defaultValues?.gender,
      color: defaultValues?.color || '',
      weight_grams: defaultValues?.weight_grams?.toString() ?? null,
      size_cm: defaultValues?.size_cm?.toString() ?? null,
      date_of_birth: toDateFieldValue(defaultValues?.date_of_birth),
      origin_country: defaultValues?.origin_country || '',
      current_location: defaultValues?.current_location || '',
      current_country: defaultValues?.current_country || '',
      current_postal_code: defaultValues?.current_postal_code || '',
      current_city: defaultValues?.current_city || '',
      intake_date: toDateFieldValue(defaultValues?.intake_date),
      character_description: defaultValues?.character_description || '',
      contract_notes: defaultValues?.contract_notes || '',
      internal_notes: defaultValues?.internal_notes || '',
    },
  })

  const currentCountry = useWatch({
    control: form.control,
    name: 'current_country',
  })

  const handleFormSubmit = async (data: AnimalFormBasicData) => {
    await onSubmit(data)
    form.reset(data)
  }

  return (
    <FormProvider {...form}>
      <form
        onSubmit={form.handleSubmit(handleFormSubmit)}
        className="space-y-6"
      >
        <FormBlocker />

        <FieldGroup>
          <FormSection
            title="Allgemeine Angaben"
            description="Die wichtigsten Informationen."
          >
            <FormGrid>
              <SelectInput
                name="animal_type_id"
                control={form.control}
                disabled={isEditMode}
                label="Tierart"
                required
                options={animalTypes.map((type) => ({
                  value: type.id,
                  label: type.title,
                }))}
                placeholder="Tierart auswählen"
              />

              <TextInput
                name="animal_number"
                control={form.control}
                label="Tiernummer"
                description={
                  isEditMode
                    ? 'Die Tiernummer kann nachträglich nicht geändert werden.'
                    : 'Leer lassen für automatische Vergabe'
                }
                disabled={isEditMode}
              />

              <TextInput
                name="name"
                control={form.control}
                label="Name"
                required
              />

              <TextInput
                name="old_name"
                control={form.control}
                label="Alter Name"
                info="Unter diesem Namen war das Tier früher bekannt."
              />

              <FormFieldWrapper
                name="gender"
                control={form.control}
                label="Geschlecht"
                required
                render={({ field }) => (
                  <RadioGroup
                    value={field.value}
                    onValueChange={field.onChange}
                    name={field.name}
                    onBlur={field.onBlur}
                  >
                    <Field orientation="horizontal">
                      <RadioGroupItem value="male" id="gender-male" />
                      <FieldLabel htmlFor="gender-male">Männlich</FieldLabel>
                    </Field>
                    <Field orientation="horizontal">
                      <RadioGroupItem value="female" id="gender-female" />
                      <FieldLabel htmlFor="gender-female">Weiblich</FieldLabel>
                    </Field>
                  </RadioGroup>
                )}
              />

              <DateInput
                name="date_of_birth"
                control={form.control}
                label="Geburtsdatum"
              />

              <TextInput name="breed" control={form.control} label="Rasse" />

              <TextInput name="color" control={form.control} label="Farbe" />

              <UnitInput
                name="weight_grams"
                control={form.control}
                label="Gewicht"
                unit="g"
              />

              <UnitInput
                name="size_cm"
                control={form.control}
                label="Größe"
                unit="cm"
              />
            </FormGrid>
          </FormSection>

          <FieldSeparator />

          <FormSection title="Herkunft">
            <FormGrid>
              <TextInput
                name="origin_country"
                control={form.control}
                label="Herkunftsland"
              />

              <TextInput
                name="current_location"
                control={form.control}
                label="Aufenthaltsort (veraltet)"
                info="Veraltet: bitte PLZ und Ort verwenden."
              />

              <TextInput
                name="current_postal_code"
                control={form.control}
                label="PLZ"
                info="Postleitzahl des Ortes, an dem das Tier lebt (z. B. Pflegestelle). Für Tiere in Deutschland Pflicht für den Export zu Tiervermittlung.de."
              />

              <TextInput
                name="current_city"
                control={form.control}
                label="Ort"
                info="Ort, an dem das Tier lebt (z. B. Pflegestelle). Für Tiere in Deutschland Pflicht für den Export zu Tiervermittlung.de."
              />

              <SelectInput
                name="current_country"
                control={form.control}
                label="Aufenthaltsland"
                info="Land, in dem das Tier gerade lebt. Wird für den Export zu Tiervermittlung.de benötigt."
                options={COUNTRY_OPTIONS}
                additionalAction={
                  <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    aria-label="Aufenthaltsland entfernen"
                    disabled={!currentCountry}
                    onClick={() =>
                      form.setValue('current_country', '', {
                        shouldDirty: true,
                      })
                    }
                  >
                    <X />
                  </Button>
                }
              />

              <DateInput
                name="intake_date"
                control={form.control}
                label="Aufnahmedatum"
              />
            </FormGrid>
          </FormSection>

          <FieldSeparator />

          <FormSection title="Beschreibungen">
            <FormGrid columns={1}>
              <Textarea
                name="character_description"
                control={form.control}
                label="Identifizierende Merkmale"
                description="Tasso Pflichtfeld"
                info="Charaktereigenschaften und besondere Merkmale, die bei der Identifizierung des Tieres helfen können. "
              />

              <Textarea
                name="contract_notes"
                control={form.control}
                label="Vertragsrelevante Informationen"
              />

              <Textarea
                name="internal_notes"
                control={form.control}
                label="Interne Notizen"
                info="Diese Notizen sind nur zur internen Verwendung und werden nie nach außen gegeben."
              />
            </FormGrid>
          </FormSection>
        </FieldGroup>

        <div className="flex justify-end gap-3">
          {onCancel && (
            <Button
              type="button"
              variant="outline"
              onClick={onCancel}
              disabled={isSubmitting}
            >
              Abbrechen
            </Button>
          )}
          {showSecondaryButton && onSecondarySubmit && (
            <Button
              type="button"
              variant="secondary"
              onClick={() => {
                form.handleSubmit(handleFormSubmit)()
                onSecondarySubmit()
              }}
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Speichert...' : 'Speichern und Neu'}
            </Button>
          )}
          <Button type="submit" disabled={isSubmitting}>
            {isSubmitting ? 'Speichert...' : 'Speichern'}
          </Button>
        </div>
      </form>
    </FormProvider>
  )
}
